// Aging: halve the counts. O(n), but rare — on a level change or every N operations
void Age() {
    var old = buckets.OrderBy(b => b.Key).ToList();   // buckets by ascending frequency
    buckets.Clear();
    minFreq = int.MaxValue;
    foreach (var (f, list) in old)
        foreach (int key in list) {                   // inside a bucket: least to most recent
            var e = map[key];
            e.freq = Math.Max(1, f / 2);
            e.node = Bucket(e.freq).AddLast(key);
            minFreq = Math.Min(minFreq, e.freq);
        }
}
